-- 主起液压供压弯管单节点数据补丁（MySQL 8）
-- 作用范围：只处理 BOM 节点 f1000006-0006-4006-8006-000000000006 / 件号 HYD-TUBE-MLG-32A / 实物 c7000001-0001-4001-8001-000000000001。
-- 说明：本补丁更新源数据表。若页面仍显示旧的已生成卷宗内容，请在导入后重新生成卷宗。

SET NAMES utf8mb4;
START TRANSACTION;

SET @aircraft_id := 'b0000001-0001-4001-8001-000000000001';
SET @bom_node_id := 'f1000006-0006-4006-8006-000000000006';
SET @part_number := 'HYD-TUBE-MLG-32A';
SET @part_instance_id := 'c7000001-0001-4001-8001-000000000001';
SET @route_code := 'R-HYD-TUBE-MLG-32A-REV-C';
SET @shop_order_id_1 := 'a1110001-0001-4001-8001-000000000001';
SET @shop_order_id_2 := 'c6000001-0001-4001-8001-000000000001';

-- 先删除这个节点的旧明细数据，避免重复执行后出现多份旧数据。
DELETE FROM t1_inspection_measurement
 WHERE part_instance_id = @part_instance_id
    OR bom_node_id = @bom_node_id
    OR inspection_record_id IN (
         SELECT id FROM t1_inspection_record
          WHERE part_instance_id = @part_instance_id
             OR bom_node_id = @bom_node_id
             OR shop_order_task_id IN (
                  SELECT id FROM t1_shop_order_task
                   WHERE part_instance_id = @part_instance_id
                      OR bom_node_id = @bom_node_id
                      OR shop_order_id IN (@shop_order_id_1, @shop_order_id_2)
             )
    );

DELETE FROM t1_inspection_record
 WHERE part_instance_id = @part_instance_id
    OR bom_node_id = @bom_node_id
    OR shop_order_task_id IN (
         SELECT id FROM t1_shop_order_task
          WHERE part_instance_id = @part_instance_id
             OR bom_node_id = @bom_node_id
             OR shop_order_id IN (@shop_order_id_1, @shop_order_id_2)
    );

DELETE FROM t1_release_record WHERE part_instance_id = @part_instance_id OR bom_node_id = @bom_node_id;

DELETE FROM t1_production_operation_record
 WHERE part_instance_id = @part_instance_id
    OR bom_node_id = @bom_node_id
    OR shop_order_task_id IN (
         SELECT id FROM t1_shop_order_task
          WHERE part_instance_id = @part_instance_id
             OR bom_node_id = @bom_node_id
             OR shop_order_id IN (@shop_order_id_1, @shop_order_id_2)
    );

DELETE FROM t1_material_lot_trace
 WHERE instance_id = @part_instance_id
    OR part_instance_id = @part_instance_id
    OR bom_node_id = @bom_node_id
    OR shop_order_task_id IN (
         SELECT id FROM t1_shop_order_task
          WHERE part_instance_id = @part_instance_id
             OR bom_node_id = @bom_node_id
             OR shop_order_id IN (@shop_order_id_1, @shop_order_id_2)
    );

DELETE FROM t1_shop_order_task
 WHERE part_instance_id = @part_instance_id
    OR bom_node_id = @bom_node_id
    OR shop_order_id IN (@shop_order_id_1, @shop_order_id_2);

DELETE FROM t1_shop_order
 WHERE id IN (@shop_order_id_1, @shop_order_id_2)
    OR part_instance_id = @part_instance_id
    OR bom_node_id = @bom_node_id;

DELETE FROM t1_process_step
 WHERE route_code = @route_code
    OR route_code IN (SELECT route_code FROM t1_process_route WHERE part_number = @part_number);
DELETE FROM t1_process_route WHERE route_code = @route_code OR part_number = @part_number;

DELETE FROM t1_impact_tube_segment WHERE model_part_number = @part_number;
DELETE FROM t1_impact_tube_fluid WHERE model_part_number = @part_number;
DELETE FROM t1_impact_tube_boundary_condition WHERE model_part_number = @part_number;
DELETE FROM t1_part_hydraulic_tube_impact_model WHERE part_number = @part_number;
DELETE FROM t1_part_parameter_value WHERE part_number = @part_number;

